    const readings=Array.from({length:count},(_,j)=>{
      const flag=(i+s+j)%11===4?'conflicting':(i+s+j)%7===2?'rejected':'accepted';
      return {time:times[j],fev:+(base+(j-1)*.045+Math.sin(i+j+s)*.025).toFixed(2),quality:flag};
    });
