  const reportingText=`In ${days.length} days: tracker entries ${now.trackerDays}/${days.length}; medication reports ${now.medicationReportDays}/${days.length}; device readings ${now.deviceReadingDays}/${days.length}. ${controllerText} Medication-report coverage: ${coverageComparison.text.replace(/[.]$/,'')}; self-reported dose-rate change: ${doseComparison.text.replace(/[.]$/,'')}.`;
