    experience:{title:'Symptoms and school impact',summary:symptomText,context:'Symptom frequency uses submitted tracker days only. Days without a tracker submission are unknown and excluded from this denominator.',kind:'symptoms'},
    lung:{title:'Accepted lung-function readings',summary:fevText,context:'The period median is calculated from each day’s best accepted reading. It is distinct from the latest daily best. Rejected and conflicting blows remain available in each day’s detail.',kind:'fev'},
