  $('clinical-insights').innerHTML=insights.map((insight,index)=>`<article class="clinical-insight"><div class="insight-number">0${index+1}</div><div class="insight-copy"><h3>${insight.title}</h3><p class="insight-summary">${insight.summary}</p><p class="insight-context">${insight.context}</p><details class="insight-evidence"><summary>Daily source records (${insight.records.length})</summary><ul>${insight.records.map(({day,period:which})=>`<li><button type="button" data-insight-date="${day.date}">${which} period - ${fmt(day.date)}</button><span>${insightSourceText(day,insight.kind)}</span></li>`).join('')}</ul></details></div></article>`).join('');
