function recentReviewSignals(key){
  const days=dataset(key),thisWeek=days.slice(-7),lastWeek=days.slice(-14,-7),signals=[];
  const currentStats=oneMinuteStats(thisWeek,patients[key].personalBest),previousStats=oneMinuteStats(lastWeek,patients[key].personalBest);
  if(currentStats.trackerDays&&previousStats.trackerDays&&currentStats.symptomRatePercent>previousStats.symptomRatePercent){const delta=rounded(currentStats.symptomRatePercent-previousStats.symptomRatePercent);signals.push({kind:'symptom',text:`Symptoms reported on ${currentStats.symptomDays}/${currentStats.trackerDays} vs ${previousStats.symptomDays}/${previousStats.trackerDays} tracker days (+${delta} percentage points vs prior 7 days)`});}
  const currentF=currentStats.medianDailyBestLiters,previousF=previousStats.medianDailyBestLiters;
  if(currentF!==null&&previousF!==null&&currentF<previousF)signals.push({kind:'fev1',text:`7-day median daily best accepted FEV1 is lower vs prior 7 days: ${currentF.toFixed(2)} vs ${previousF.toFixed(2)} L (${currentStats.acceptedDailyBestDays} vs ${previousStats.acceptedDailyBestDays} days with accepted readings)`});
  if(thisWeek.slice(-3).length===3&&thisWeek.slice(-3).every(d=>!(d.trackerSubmitted??!d.missing)))signals.push({kind:'gap',text:'No tracker submission on the last 3 days'});
  const symptomDays=currentStats.symptomDays;
  return {signals,symptomDays,symptomRatePercent:currentStats.symptomRatePercent,trackerDays:currentStats.trackerDays,
    medicationReportDays:currentStats.medicationReportDays,deviceReadingDays:currentStats.deviceReadingDays,
    missing:thisWeek.filter(d=>!(d.trackerSubmitted??!d.missing)).length};
}
function comparePatientPriority(a,b){return b.signals.length-a.signals.length||(b.symptomRatePercent??-1)-(a.symptomRatePercent??-1)||a.p.name.localeCompare(b.p.name);}
